    private val lowerMap: Map<String, Map<AppCountry, String>> = map.entries.associate { (k, v) -> k.lowercase() to v }

    fun translate(text: String, country: AppCountry): String {
        if (country == AppCountry.VN || text.isBlank()) return text
        val trimmed = text.trim()
        map[trimmed]?.get(country)?.let { return it }
        lowerMap[trimmed.lowercase()]?.get(country)?.let { return it }
        return text
    }
}
